class Solution {
  public int minZeroArray(int[] nums, int[][] queries) {
    int n = nums.length;
    boolean[][] dp = new boolean[n][];
    for (int i = 0; i < n; i++) {
      dp[i] = new boolean[nums[i] + 1];
      dp[i][0] = true;
    }
    if (done(nums, dp)) return 0;
    for (int q = 0; q < queries.length; q++) {
      int l = queries[q][0], r = queries[q][1], v = queries[q][2];
      for (int i = l; i <= r; i++) {
        for (int s = nums[i]; s >= v; s--) if (dp[i][s - v]) dp[i][s] = true;
      }
      if (done(nums, dp)) return q + 1;
    }
    return -1;
  }

  private static boolean done(int[] nums, boolean[][] dp) {
    for (int i = 0; i < nums.length; i++) if (!dp[i][nums[i]]) return false;
    return true;
  }
}
